#include <array>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int k;
    string s;
    cin >> k >> s;

    const int n = static_cast<int>(s.size());
    vector<int> freePairs;

    for (int i = 0; i <= (n - 1) / 2; ++i) {
        int j = n - 1 - i;

        if (s[i] != '?' && s[j] != '?' && s[i] != s[j]) {
            cout << "IMPOSSIBLE";
            return 0;
        }

        if (s[i] == '?' && s[j] != '?') {
            s[i] = s[j];
        } else if (s[i] != '?' && s[j] == '?') {
            s[j] = s[i];
        } else if (s[i] == '?' && s[j] == '?') {
            freePairs.push_back(i);
        }
    }

    array<bool, 26> used{};
    int distinct = 0;

    for (char c : s) {
        if (c != '?' && !used[c - 'a']) {
            used[c - 'a'] = true;
            ++distinct;
        }
    }

    if (k < distinct || k > 26 || static_cast<int>(freePairs.size()) < k - distinct) {
        cout << "IMPOSSIBLE";
        return 0;
    }

    vector<char> missing;
    for (int c = 25; c >= 0 && distinct < k; --c) {
        if (!used[c]) {
            missing.push_back(static_cast<char>('a' + c));
            used[c] = true;
            ++distinct;
        }
    }

    for (char c : missing) {
        int i = freePairs.back();
        freePairs.pop_back();
        int j = n - 1 - i;
        s[i] = s[j] = c;
    }

    char fill = 'a';
    for (int c = 0; c < 26; ++c) {
        if (used[c]) {
            fill = static_cast<char>('a' + c);
            break;
        }
    }

    while (!freePairs.empty()) {
        int i = freePairs.back();
        freePairs.pop_back();
        int j = n - 1 - i;
        s[i] = s[j] = fill;
    }

    cout << s;
    return 0;
}

