int main() {
    int k;
    string s;
    cin >> k >> s;

    const int n = static_cast<int>(s.size());
    vector<int> unknownPairs;
    vector<bool> used(k, false);

    for (int i = 0; i < (n + 1) / 2; ++i) {
        int j = n - 1 - i;

        if (s[i] != '?' && s[j] != '?' && s[i] != s[j]) {
            cout << "IMPOSSIBLE";
            return 0;
        }

        if (s[i] == '?' && s[j] != '?') {
            s[i] = s[j];
        } else if (s[i] != '?' && s[j] == '?') {
            s[j] = s[i];
        } else if (s[i] == '?' && s[j] == '?') {
            unknownPairs.push_back(i);
        }
    }

    for (char c : s) {
        if (c == '?') continue;
        if (c < 'a' || c >= 'a' + k) {
            cout << "IMPOSSIBLE";
            return 0;
        }
        used[c - 'a'] = true;
    }

    vector<char> missing;
    for (int i = k - 1; i >= 0; --i) {
        if (!used[i]) missing.push_back(static_cast<char>('a' + i));
    }

    if (missing.size() > unknownPairs.size()) {
        cout << "IMPOSSIBLE";
        return 0;
    }

    for (char c : missing) {
        int i = unknownPairs.back();
        unknownPairs.pop_back();
        s[i] = s[n - 1 - i] = c;
    }

    for (int i : unknownPairs) {
        s[i] = s[n - 1 - i] = 'a';
    }

    cout << s;
    return 0;
}

