int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int k;
    string s;
    cin >> k >> s;

    if (k < 0 || k > 26) {
        cout << "IMPOSSIBLE";
        return 0;
    }

    vector<int> unknown;
    const int n = static_cast<int>(s.size());

    for (int i = 0; i <= n - 1 - i; ++i) {
        int j = n - 1 - i;

        if (s[i] != '?' && s[j] != '?' && s[i] != s[j]) {
            cout << "IMPOSSIBLE";
            return 0;
        }

        if (s[i] == '?' && s[j] != '?') {
            s[i] = s[j];
        } else if (s[i] != '?' && s[j] == '?') {
            s[j] = s[i];
        } else if (s[i] == '?' && s[j] == '?') {
            unknown.push_back(i);
        }
    }

    array<bool, 26> used{};
    int distinct = 0;

    for (char c : s) {
        if (c != '?' && !used[c - 'a']) {
            used[c - 'a'] = true;
            ++distinct;
        }
    }

    int needed = k - distinct;
    if (needed < 0 || needed > static_cast<int>(unknown.size())) {
        cout << "IMPOSSIBLE";
        return 0;
    }

    size_t pos = 0;
    for (int c = 0; c < 26 && needed > 0; ++c) {
        if (!used[c]) {
            int i = unknown[pos++];
            s[i] = s[n - 1 - i] = static_cast<char>('a' + c);
            used[c] = true;
            --needed;
        }
    }

    char fill = 'a';
    for (int c = 0; c < 26; ++c) {
        if (used[c]) {
            fill = static_cast<char>('a' + c);
            break;
        }
    }

    while (pos < unknown.size()) {
        int i = unknown[pos++];
        s[i] = s[n - 1 - i] = fill;
    }

    cout << s;
    return 0;
}

